import { Handle, Position, type NodeProps } from "reactflow";
import { NodeState, type CanvasNodeData } from "../../types";
import { nodePropsToNodeObject } from "../../utils";
import { getBorderColor } from "../../utils/canvas";
import { Content } from "./Content";
import { SharedBox } from "./SharedBox";

export const StandardNode = (props: NodeProps<CanvasNodeData>) => {
  const {
    isConnectable,
    targetPosition,
    sourcePosition,
    data: { nodeState },
  } = props;
  const node = nodePropsToNodeObject(props);
  const isActive = nodeState === NodeState.Active;
  const boxSx: {
    pointerEvents: string;
    borderColor: string;
    _hover?: { boxShadow: string; cursor: string };
    borderWidth: string;
  } = {
    pointerEvents: "all",
    borderColor: getBorderColor(nodeState),
    borderWidth: isActive ? "2px" : "1px",
  };

  return (
    <>
      <Handle
        type="target"
        position={targetPosition || Position.Top}
        isConnectable={false}
        style={{
          top: -0.25,
        }}
      />
      <SharedBox tabIndex={0} css={boxSx} data-testid={isActive ? "node-selected" : "node"}>
        <Content node={node} />
      </SharedBox>

      <Handle
        type="source"
        position={sourcePosition || Position.Bottom}
        isConnectable={isConnectable}
        style={{
          bottom: 0,
        }}
      />

      <Handle type="source" position={Position.Left} isConnectable={isConnectable} />
      <Handle type="target" position={Position.Right} isConnectable={isConnectable} />
      <Handle type="target" position={Position.Left} isConnectable={isConnectable} />
      <Handle type="source" position={Position.Right} isConnectable={isConnectable} />
    </>
  );
};
